sp_widget.client_script:
api.controller = function($location) {
    var c = this;
    c.currentPage = c.data.currentPage || 1;

    c.goToPage = function(page) {
        if (page < 1 || page > c.data.totalPages) return;
        c.currentPage = page;
        c.server.get({ page: page }).then(function() {
            c.currentPage = c.data.currentPage;
        });
    };

    c.viewDetail = function(sysId) {
        var url = '?id=x_1956908_wareho_0_detail&record_id=' + sysId;
        window.location.href = url;
    };
};

sp_widget.css:
.exc-table-widget {
  margin-bottom: 20px;
}

.exc-table-header {
  background-color: $brand-primary;
  color: #fff;
  border: none;
}

.exc-table-header .panel-title {
  font-weight: 600;
}

.exc-table-header .badge {
  background-color: rgba(255,255,255,0.2);
  color: #fff;
}

.exc-table-widget .table thead th {
  border-bottom: 2px solid #ddd;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #666;
}

.exc-table-widget .table tbody td {
  vertical-align: middle;
}

.exc-table-widget .label {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 3px;
}

.exc-table-widget .pagination {
  margin: 10px 0 0 0;
}

sp_widget.script:
(function() {
    var tableName = 'x_1956908_wareho_0_exception';
    var userId = gs.getUserID();
    var pageSize = 10;
    var page = (input && input.page) ? parseInt(input.page, 10) : 1;
    if (page < 1) page = 1;

    data.records = [];
    data.title = options.title || 'Exceptions';
    data.currentPage = page;
    data.totalPages = 1;

    // Determine effective role
    var role = options.role || 'staff';
    if (gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin')) {
        if (!options.role) role = 'supervisor';
    } else if (gs.hasRole('x_1956908_wareho_0.technician')) {
        if (!options.role) role = 'technician';
    }

    // Build base query
    var baseQuery = '';
    if (role === 'staff') {
        baseQuery = 'reported_by=' + userId;
    } else if (role === 'technician') {
        baseQuery = 'assigned_to=' + userId;
    }

    // Optional extra filter from widgetParameters
    var extraFilter = options.filter || '';
    if (extraFilter && baseQuery) {
        baseQuery = baseQuery + '^' + extraFilter;
    } else if (extraFilter) {
        baseQuery = extraFilter;
    }

    // Count total records
    var countGr = new GlideAggregate(tableName);
    if (baseQuery) {
        countGr.addEncodedQuery(baseQuery);
    }
    countGr.addAggregate('COUNT');
    countGr.query();
    var total = 0;
    if (countGr.next()) {
        total = parseInt(countGr.getAggregate('COUNT'), 10);
    }
    data.totalPages = Math.max(1, Math.ceil(total / pageSize));
    data.totalRecords = total;

    if (page > data.totalPages) page = data.totalPages;
    data.currentPage = page;

    // Status badge mapping
    var STATUS_CLASS = {
        'new': 'label-info',
        'assigned': 'label-warning',
        'in_progress': 'label-primary',
        'pending': 'label-default',
        'resolved': 'label-success',
        'closed': 'label-default'
    };

    // Priority badge mapping
    var PRIORITY_CLASS = {
        'p1_critical': 'label-danger',
        'p2_high': 'label-warning',
        'p3_medium': 'label-info',
        'p4_low': 'label-success'
    };

    // Query records
    var gr = new GlideRecord(tableName);
    if (baseQuery) {
        gr.addEncodedQuery(baseQuery);
    }
    gr.orderByDesc('sys_created_on');
    gr.chooseWindow((page - 1) * pageSize, page * pageSize);
    gr.query();

    while (gr.next()) {
        data.records.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') || '',
            exception_type: gr.getDisplayValue('exception_type'),
            location: gr.getValue('location') || '',
            priority: gr.getDisplayValue('priority'),
            priorityVal: gr.getValue('priority') || '',
            priorityClass: PRIORITY_CLASS[gr.getValue('priority')] || 'label-default',
            status: gr.getDisplayValue('status'),
            statusVal: gr.getValue('status') || '',
            statusClass: STATUS_CLASS[gr.getValue('status')] || 'label-default',
            created: gr.getDisplayValue('sys_created_on'),
            updated: gr.getDisplayValue('sys_updated_on')
        });
    }

    // Build page numbers array
    data.pages = [];
    for (var i = 1; i <= data.totalPages; i++) {
        data.pages.push(i);
    }
})();
